import { thoughtSpotHost } from '../config/thoughtspot';

const BASE = thoughtSpotHost;

async function loginSession(): Promise<void> {
  await fetch(`${BASE}/api/rest/2.0/auth/session/login`, {
    method: 'POST',
    credentials: 'include',
    headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
    body: JSON.stringify({
      username: 'katie.matkin@thoughtspot.com',
      password: 'Sheffield.1!',
    }),
  });
}

export interface SearchResult {
  columnNames: string[];
  rows: any[][];
}

export async function searchData(
  modelId: string,
  queryString: string,
): Promise<SearchResult> {
  // Ensure session exists
  await loginSession();

  const res = await fetch(`${BASE}/api/rest/2.0/searchdata`, {
    method: 'POST',
    credentials: 'include',
    headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
    body: JSON.stringify({
      query_string: queryString,
      logical_table_identifier: modelId,
      record_size: 1,
      record_offset: 0,
    }),
  });

  if (!res.ok) throw new Error(`searchData failed: ${res.status}`);

  const json = await res.json();
  const content = json?.contents?.[0];
  return {
    columnNames: content?.column_names ?? [],
    rows: content?.data_rows ?? [],
  };
}
